SELECT io.*, m.name as material_name, m.code as material_code, m.unit_id as unit_id, m.specification as material_spec, io.create_by as request_user_id, COALESCE(io.finished_time, io.terminate_time) AS orderEndTime, io.create_time as request_time, s.name as scheme_name, sv.version_no as scheme_version FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id left join lm_inspection_scheme s ON sv.scheme_id = s.id WHERE io.is_deleted = 0
AND io.order_no LIKE CONCAT('%', #{param.orderNo}, '%')
AND io.material_id IN
#{mid}
AND m.name LIKE CONCAT('%', #{param.materialName}, '%')
AND m.code LIKE CONCAT('%', #{param.materialCode}, '%')
AND io.batch_no LIKE CONCAT('%', #{param.batchNo}, '%')
AND io.order_status IN
#{st}
AND io.create_by in
#{rid}
AND io.create_time >= #{param.inspectionRequestTimeStart}
AND io.create_time <= #{param.inspectionRequestTimeEnd}
AND io.scheme_source = #{param.schemeSource}
ORDER BY io.create_time DESC

SELECT io.id, io.order_no AS orderNo, io.material_id AS materialId, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, io.batch_no AS batchNo, io.create_time AS createTime, io.create_by AS createBy, io.create_time AS request_time, io.create_by AS request_user_id, io.remark FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE io.is_deleted = 0 AND io.order_status = 'CONFIRMED' AND (io.report_approved IS NULL OR io.report_approved = 0) AND io.report_approval_process_instance_id IS NOT NULL
AND io.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND m.name LIKE CONCAT('%', #{query.materialName}, '%')
AND m.code LIKE CONCAT('%', #{query.materialCode}, '%')
AND io.material_id IN
#{mid}
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.inspectionRequestTimeStart}
AND io.create_time <= #{query.inspectionRequestTimeEnd}
ORDER BY io.create_time ASC

SELECT DISTINCT io.*, m.name as material_name, m.code as material_code, m.specification as material_spec, io.create_by as request_user_id, io.create_time as request_time, s.name as scheme_name, sv.version_no as scheme_version FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id LEFT JOIN lm_inspection_scheme s ON sv.scheme_id = s.id WHERE io.is_deleted = 0 AND io.order_status = 'COMPLETED'
AND io.order_no LIKE CONCAT('%', #{param.orderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{param.batchNo}, '%')
AND io.create_time >= #{param.inspectionRequestTimeStart}
AND io.create_time <= #{param.inspectionRequestTimeEnd}
AND io.material_id IN
#{mid}
ORDER BY io.create_time DESC

SELECT DISTINCT io.id, io.order_no AS orderNo, io.material_id AS materialId, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, io.batch_no AS batchNo, io.create_time AS createTime, io.create_by AS createBy, io.create_time as request_time, io.create_by AS request_user_id, io.remark FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE io.is_deleted = 0 AND io.order_status = 'CONFIRMED' AND EXISTS ( SELECT 1 FROM lm_sample s WHERE s.inspection_order_id = io.id AND s.sampled = 1 AND s.is_deleted = 0 AND (s.inspect_item_id IS NULL OR s.inspect_item_id != 2000000000000000001) ) AND EXISTS ( SELECT 1 FROM lm_sample s WHERE s.inspection_order_id = io.id AND s.sampled = 1 AND s.received = 0 AND s.is_deleted = 0 AND (s.inspect_item_id IS NULL OR s.inspect_item_id != 2000000000000000001) )
AND io.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND m.name LIKE CONCAT('%', #{query.materialName}, '%')
AND m.code LIKE CONCAT('%', #{query.materialCode}, '%')
AND io.material_id IN
#{mid}
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.inspectionRequestTimeStart}
AND io.create_time <= #{query.inspectionRequestTimeEnd}
ORDER BY io.create_time DESC

SELECT DISTINCT io.*, m.name as material_name, m.code as material_code, m.specification as material_spec, io.create_by as request_user_id, io.create_time as request_time, s.name as scheme_name, sv.version_no as scheme_version FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id left join lm_inspection_scheme s ON sv.scheme_id = s.id WHERE io.is_deleted = 0 AND io.order_status = 'CONFIRMED' AND (io.scheme_source IS NULL OR io.scheme_source != 'STABILITY') AND EXISTS ( SELECT 1 FROM lm_sample s0 WHERE s0.inspection_order_id = io.id AND s0.sampled = 0 AND s0.discarded = 0 AND s0.is_deleted = 0 )
AND io.material_id IN
#{mid}
AND io.order_no LIKE CONCAT('%', #{param.orderNo}, '%')
AND m.name LIKE CONCAT('%', #{param.materialName}, '%')
AND io.batch_no LIKE CONCAT('%', #{param.batchNo}, '%')
AND io.create_time >= #{param.inspectionRequestTimeStart}
AND io.create_time <= #{param.inspectionRequestTimeEnd}
ORDER BY io.create_time DESC

SELECT io.id, io.order_no AS orderNo, io.material_id AS materialId, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, io.batch_no AS batchNo, io.create_time AS createTime, io.create_by AS createBy, io.create_time AS request_time, io.create_by AS request_user_id, io.remark FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE io.is_deleted = 0 AND io.order_status = 'SAMPLE_AUDIT_PENDING' AND io.sample_audit_process_instance_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM lm_stability_plan_timepoint_task tpt WHERE tpt.inspection_order_id = io.id AND tpt.is_deleted = 0 )
AND io.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND m.name LIKE CONCAT('%', #{query.materialName}, '%')
AND m.code LIKE CONCAT('%', #{query.materialCode}, '%')
AND io.material_id IN
#{mid}
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.inspectionRequestTimeStart}
AND io.create_time <= #{query.inspectionRequestTimeEnd}
ORDER BY io.create_time ASC

SELECT io.id, io.order_no AS orderNo, io.create_time AS requestTime, m.name AS materialName, sv.version_no AS schemeVersionNo FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id
io.is_deleted = 0
AND io.material_id = #{query.materialId}
AND io.scheme_version_id = #{query.schemeVersionId}
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
ORDER BY io.create_time DESC, io.id DESC

SELECT io.id, io.order_no AS orderNo, io.create_time AS requestTime, m.name AS materialName, sv.version_no AS schemeVersionNo FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id
io.is_deleted = 0
AND sv.scheme_id = #{query.schemeId}
AND io.order_status = #{query.orderStatus}
ORDER BY io.create_time DESC, io.id DESC

